import sys
from collections import deque

def bfs(grid, N, M):
    queue = deque([(0, 0)])
    visited = [[False] * M for _ in range(N)]
    visited[0][0] = True
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while queue:
        x, y = queue.popleft()
        if x == N - 1 and y == M - 1:
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny))
    return False

def solve():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    results = []

    T = int(input[index])
    index += 1

    for _ in range(T):
        N, M = map(int, input[index].split())
        index += 1
        grid = [list(input[index + i]) for i in range(N)]
        index += N

        if bfs(grid, N, M):
            results.append(0)
            continue

        rows_with_walls = set()
        cols_with_walls = set()

        for i in range(N):
            for j in range(M):
                if grid[i][j] == '#':
                    rows_with_walls.add(i)
                    cols_with_walls.add(j)

        min_airstrikes = float('inf')

        for r in rows_with_walls:
            for c in cols_with_walls:
                grid[r][c] = '.'
                if bfs(grid, N, M):
                    min_airstrikes = min(min_airstrikes, 1)
                grid[r][c] = '#'

        if min_airstrikes == float('inf'):
            min_airstrikes = 2

        results.append(min_airstrikes)

    for result in results:
        print(result)

solve()
